import assert from 'node:assert/strict';
import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
const base = 'skills/allocation-profiling';
const files = [base + '/SKILL.md', ...readdirSync(base + '/references').filter(n => n.endsWith('.md')).map(n => base + '/references/' + n)];
let links = 0;
for (const file of files) {
  const body = readFileSync(file, 'utf8');
  for (const match of body.matchAll(/\[[^\]]*\]\((?:<([^>]+)>|([^\s)]+))\)/g)) {
    const target = match[1] || match[2];
    if (/^https?:/.test(target)) continue;
    const [path, anchor] = target.split('#');
    const dest = path ? resolve(dirname(file), path) : resolve(file);
    assert.ok(existsSync(dest), file + ': missing ' + target);
    if (anchor) {
      const headings = readFileSync(dest, 'utf8').split('\n').filter(l => /^#+ /.test(l)).map(l => l.replace(/^#+ /, '').toLowerCase().replace(/[^\w -]/g, '').replaceAll(' ', '-'));
      assert.ok(headings.includes(anchor), file + ': missing anchor ' + target);
    }
    links++;
  }
}
assert.ok(existsSync('skills/flame-graph-analysis/SKILL.md'));
const cases = {
  overlap: [['Request.run;Serialize.encode;Copy.buffer;byte[]', 40000000], ['Request.run;Serialize.encode;StringBuilder.toString;byte[]', 20000000], ['Request.run;Other.work;byte[]', 40000000]],
  disjoint: [['Request.run;Serialize.encode;byte[]', 60000000], ['Request.run;Copy.buffer;byte[]', 40000000]],
};
for (const [name, rows] of Object.entries(cases)) {
  const includes = (stack, frame) => stack.split(';').includes(frame);
  const frames = ['Serialize.encode', 'Copy.buffer'];
  const inclusive = frames.map(frame => rows.reduce((sum, [stack, weight]) => sum + (includes(stack, frame) ? weight : 0), 0));
  const union = rows.reduce((sum, [stack, weight]) => sum + (frames.some(frame => includes(stack, frame)) ? weight : 0), 0);
  assert.deepEqual(inclusive, [60000000, 40000000]);
  assert.equal(union, name === 'overlap' ? 60000000 : 100000000);
  assert.equal(rows.reduce((sum, [, weight]) => sum + weight, 0), 100000000);
  console.log(name + ': inclusive=' + inclusive.join('+') + ' B; union=' + union + ' B; attributed=' + union / 1000 + ' B/completion');
}
console.log('PASS: ' + links + ' local resource links, including candidate anchor; optional skill exists; 2 allocation arithmetic cases');
